from pathlib import Path

path = Path("app/src/main/java/com/mixtervee/fastmagnifier/ScreenMagnifierService.kt")
text = path.read_text(encoding="utf-8")

# Remove the visible yellow L-shaped views from the image area. Keep the large
# transparent corner hit targets so resizing remains easy to grab.
old_handles = '''        fun addCornerHandle(gravity: Int, corner: Int) {\n            val handle = FrameLayout(this).apply {\n                contentDescription = "Resize magnifier"\n                setOnTouchListener { _, event -> handleCornerResize(event, corner) }\n            }\n\n            // Keep the grab target comfortably large, but draw only thin yellow\n            // border segments so the resize affordance does not cover magnified text.\n            val horizontal = View(this).apply { setBackgroundColor(Color.YELLOW) }\n            val vertical = View(this).apply { setBackgroundColor(Color.YELLOW) }\n\n            val top = corner == 0 || corner == 1\n            val start = corner == 0 || corner == 2\n            val verticalGravity = if (top) Gravity.TOP else Gravity.BOTTOM\n            val horizontalGravity = if (start) Gravity.START else Gravity.END\n\n            handle.addView(\n                horizontal,\n                FrameLayout.LayoutParams(\n                    dp(24),\n                    dp(3),\n                    verticalGravity or horizontalGravity\n                )\n            )\n            handle.addView(\n                vertical,\n                FrameLayout.LayoutParams(\n                    dp(3),\n                    dp(24),\n                    verticalGravity or horizontalGravity\n                )\n            )\n\n            imageFrame.addView(\n                handle,\n                FrameLayout.LayoutParams(dp(46), dp(46), gravity)\n            )\n        }'''

new_handles = '''        fun addCornerHandle(gravity: Int, corner: Int) {\n            val handle = FrameLayout(this).apply {\n                // Invisible 46dp hit target. The visual indicator is now drawn\n                // directly into the outer border instead of over the image.\n                contentDescription = "Resize magnifier"\n                setOnTouchListener { _, event -> handleCornerResize(event, corner) }\n            }\n            imageFrame.addView(\n                handle,\n                FrameLayout.LayoutParams(dp(46), dp(46), gravity)\n            )\n        }'''

if old_handles not in text:
    raise SystemExit("Could not find yellow corner overlay block")
text = text.replace(old_handles, new_handles, 1)

old_background = '''            background = GradientDrawable().apply {\n                shape = GradientDrawable.RECTANGLE\n                setColor(Color.argb(245, 15, 18, 24))\n                setStroke(dp(3), CYAN)\n                cornerRadius = dp(16).toFloat()\n            }'''

new_background = '''            background = object : android.graphics.drawable.Drawable() {\n                private val fillPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {\n                    color = Color.argb(245, 15, 18, 24)\n                    style = android.graphics.Paint.Style.FILL\n                }\n                private val cyanPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {\n                    color = CYAN\n                    style = android.graphics.Paint.Style.STROKE\n                    strokeWidth = dp(3).toFloat()\n                    strokeJoin = android.graphics.Paint.Join.ROUND\n                }\n                private val yellowPaint = android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG).apply {\n                    color = Color.YELLOW\n                    style = android.graphics.Paint.Style.STROKE\n                    strokeWidth = dp(3).toFloat()\n                    strokeJoin = android.graphics.Paint.Join.ROUND\n                    strokeCap = android.graphics.Paint.Cap.SQUARE\n                }\n\n                override fun draw(canvas: android.graphics.Canvas) {\n                    val halfStroke = dp(3) / 2f\n                    val left = bounds.left + halfStroke\n                    val top = bounds.top + halfStroke\n                    val right = bounds.right - halfStroke\n                    val bottom = bounds.bottom - halfStroke\n                    val radius = dp(16).toFloat()\n                    val leg = dp(26).toFloat()\n                    val rect = android.graphics.RectF(left, top, right, bottom)\n\n                    canvas.drawRoundRect(rect, radius, radius, fillPaint)\n                    canvas.drawRoundRect(rect, radius, radius, cyanPaint)\n\n                    fun cornerPath(corner: Int): android.graphics.Path {\n                        return android.graphics.Path().apply {\n                            when (corner) {\n                                0 -> {\n                                    moveTo(left, top + leg)\n                                    lineTo(left, top + radius)\n                                    quadTo(left, top, left + radius, top)\n                                    lineTo(left + leg, top)\n                                }\n                                1 -> {\n                                    moveTo(right - leg, top)\n                                    lineTo(right - radius, top)\n                                    quadTo(right, top, right, top + radius)\n                                    lineTo(right, top + leg)\n                                }\n                                2 -> {\n                                    moveTo(left, bottom - leg)\n                                    lineTo(left, bottom - radius)\n                                    quadTo(left, bottom, left + radius, bottom)\n                                    lineTo(left + leg, bottom)\n                                }\n                                else -> {\n                                    moveTo(right - leg, bottom)\n                                    lineTo(right - radius, bottom)\n                                    quadTo(right, bottom, right, bottom - radius)\n                                    lineTo(right, bottom - leg)\n                                }\n                            }\n                        }\n                    }\n\n                    for (corner in 0..3) {\n                        canvas.drawPath(cornerPath(corner), yellowPaint)\n                    }\n                }\n\n                override fun setAlpha(alpha: Int) {\n                    fillPaint.alpha = alpha\n                    cyanPaint.alpha = alpha\n                    yellowPaint.alpha = alpha\n                    invalidateSelf()\n                }\n\n                override fun setColorFilter(colorFilter: android.graphics.ColorFilter?) {\n                    fillPaint.colorFilter = colorFilter\n                    cyanPaint.colorFilter = colorFilter\n                    yellowPaint.colorFilter = colorFilter\n                    invalidateSelf()\n                }\n\n                @Suppress("DEPRECATION")\n                override fun getOpacity(): Int = PixelFormat.TRANSLUCENT\n            }'''

if old_background not in text:
    raise SystemExit("Could not find magnifier border background")
text = text.replace(old_background, new_background, 1)

path.write_text(text, encoding="utf-8")
print("Integrated yellow resize indicators directly into the cyan rounded border")
